/// Circuit state for one processing channel (nodal solver).
///
/// Contains per-sample state and sample-rate-dependent matrices.
/// Call [`set_sample_rate`](CircuitState::set_sample_rate) before processing
/// if the host sample rate differs from [`SAMPLE_RATE`].
#[derive(Clone, Debug)]
pub struct CircuitState {
    /// Previous node voltages v[n-1]
    pub v_prev: [f64; N],

    /// Previous nonlinear currents i_nl[n-1]
    pub i_nl_prev: [f64; M],

    /// Nonlinear currents from two samples ago i_nl[n-2] (for NR predictor)
    pub i_nl_prev_prev: [f64; M],

    /// DC operating point (for reset/sleep/wake)
    pub dc_operating_point: [f64; N],

    /// Previous input sample for trapezoidal integration
    pub input_prev: f64,

    /// NR convergence diagnostic from the last sample's solve.
    ///
    /// Semantics:
    /// - 0..MAX_ITER-1: 0-indexed iteration at which convergence was detected
    ///   (i.e. `last_nr_iterations + 1` iterations actually ran)
    /// - MAX_ITER: loop exhausted without convergence → NR failed
    ///
    /// The check `last_nr_iterations >= MAX_ITER` is the BE-fallback trigger;
    /// storing `iter` (not `iter + 1`) is intentional so that convergence at
    /// the final permitted iteration (iter == MAX_ITER - 1) does not false-trigger.
    pub last_nr_iterations: u32,

    /// Diagnostic: peak absolute output (pre-clamp)
    pub diag_peak_output: f64,
    /// Diagnostic: number of times output exceeded the ±output_clamp_v ceiling
    pub diag_clamp_count: u64,
    /// Diagnostic: number of times NR hit max iterations
    pub diag_nr_max_iter_count: u64,
    /// Diagnostic: device-samples where a pentode's grid conducts (Vgk > 0)
    /// or a BJT's base-collector junction is forward biased (saturation) —
    /// the regions the grid-off / forward-active reductions assume are never
    /// entered. Counted on the full models too (characterization, not a guard).
    pub diag_region_exit_count: u64,
    /// Diagnostic: number of backward Euler fallback activations
    pub diag_be_fallback_count: u64,
    /// Diagnostic: number of times the runtime BE-latch engaged (rising
    /// edges). Nonzero means the solver detected a self-sustaining Nyquist
    /// limit cycle on this stream and permanently switched that instance to
    /// the L-stable backward-Euler path (cleared by reset()). A plugin can
    /// surface this as "solver degraded". Always 0 on backward-Euler and
    /// force-trap builds.
    pub diag_be_latch_count: u64,
    /// Diagnostic: number of samples where the active-set rail resolve
    /// pinned at least one op-amp output (ActiveSet/ActiveSetBe only)
    pub diag_active_set_pin_count: u64,
    /// Diagnostic: number of times NaN triggered state reset
    pub diag_nan_reset_count: u64,
    /// Diagnostic: number of times a finite-but-implausible iterate
    /// (state magnitude beyond any physically-realizable circuit value)
    /// triggered state reset. NaN/Inf is caught by diag_nan_reset_count;
    /// this counts the "diverged but still is_finite()" gap.
    pub diag_magnitude_reset_count: u64,
    /// Diagnostic: number of samples that needed adaptive sub-stepping
    pub diag_substep_count: u64,
    /// Diagnostic: number of LU refactorizations performed
    pub diag_refactor_count: u64,
    /// Diagnostic: number of NR iterations whose Armijo line search was
    /// searched and failed (no `s` down to the 2^-10 floor met the
    /// sufficient-decrease test on a finite r0 > 1e-9). On such an
    /// iteration the loop takes the un-line-searched pnjlim/damp-limited
    /// step and continues; the always-checked residual gate still decides
    /// convergence. This is an expected event on stiff high-gain circuits,
    /// not an error — it is surfaced (not silenced) so the fall-through is
    /// observable. A non-finite or <=1e-9 r0 skips the search entirely and
    /// does NOT count here (ls_ok stays true).
    pub diag_ls_fail_count: u64,
    /// Diagnostic: number of samples hit by the global voltage-damping
    /// safety net. This is a legacy safeguard that scales v_new toward
    /// v_prev when any node moves more than ~2V (or 5% of max DC OP) in
    /// one sample. Per CLAUDE.md, output limiting must never mask solver
    /// bugs — treat a nonzero count here as a signal that the solver needs
    /// investigation, not as an acceptable steady-state.
    pub diag_voltage_damp_count: u64,

    // --- Cross-timestep chord method state (persisted LU factors) ---
    /// LU-factored Jacobian from previous convergence (chord method)
    pub chord_lu: [[f64; N]; N],
    /// Row equilibration scaling from LU factorization
    pub chord_dr: [f64; N],
    /// Column equilibration scaling from LU factorization
    pub chord_dc: [f64; N],
    /// Row permutation from LU factorization
    pub chord_perm: [usize; N],
    /// Device Jacobian consistent with chord_lu (for companion RHS)
    pub chord_j_dev: [f64; M * M],
    /// Whether chord LU factors are valid (false until first convergence)
    pub chord_valid: bool,
    /// Whether chord_lu holds DENSE (partial-pivoting) factors from the
    /// runtime fallback (sparse static pivoting rejected: tiny pivot or
    /// excessive element growth). Selects the matching back-solve.
    pub chord_dense: bool,

    /// A matrix: G + alpha*C (trapezoidal), recomputed by set_sample_rate
    pub a: [[f64; N]; N],
    /// A_neg matrix: alpha*C - G (trapezoidal history), recomputed by set_sample_rate
    pub a_neg: [[f64; N]; N],
    /// A_be matrix: G + (1/T)*C (backward Euler), recomputed by set_sample_rate
    pub a_be: [[f64; N]; N],
    /// A_neg_be matrix: (1/T)*C (backward Euler history), recomputed by set_sample_rate
    pub a_neg_be: [[f64; N]; N],
    /// S matrix: A^{-1} (trapezoidal), recomputed by set_sample_rate
    pub s: [[f64; N]; N],
    /// K matrix: N_v * S * N_i (nonlinear kernel), recomputed by set_sample_rate
    pub k: [[f64; M]; M],
    /// S_NI matrix: S * N_i (voltage recovery), recomputed by set_sample_rate
    pub s_ni: [[f64; M]; N],
    /// S_be matrix: A_be^{-1} (backward Euler), recomputed by set_sample_rate
    pub s_be: [[f64; N]; N],
    /// K_be matrix: N_v * S_be * N_i (BE kernel), recomputed by set_sample_rate
    pub k_be: [[f64; M]; M],
    /// S_NI_be matrix: S_be * N_i (BE voltage recovery), recomputed by set_sample_rate
    pub s_ni_be: [[f64; M]; N],
    /// S_sub matrix: (G+4C/T)^{-1} (trap at 2× rate), recomputed by set_sample_rate
    pub s_sub: [[f64; N]; N],
    /// A_neg_sub matrix: 4C/T-G (trap at 2× rate history), recomputed by set_sample_rate
    pub a_neg_sub: [[f64; N]; N],
    /// K_sub matrix: N_v*S_sub*N_i (sub-step kernel)
    pub k_sub: [[f64; M]; M],
    /// S_NI_sub matrix: S_sub*N_i (sub-step voltage recovery)
    pub s_ni_sub: [[f64; M]; N],

    /// Working G matrix (modified by pots/switches)
    pub g_work: [[f64; N]; N],
    /// Working C matrix (modified by switches/saturating inductors)
    pub c_work: [[f64; N]; N],
    /// Current HOST sample rate (Hz), as passed to `set_sample_rate`.
    /// Multiply by `OVERSAMPLING_FACTOR` to get the internal rate at
    /// consumption sites (rebuild_matrices, op-amp slew dt, substep
    /// alpha). Matches the DK path's field semantics (API parity).
    pub current_sample_rate: f64,
    /// Lazy rebuild flag: set by set_pot/set_switch, cleared by process_sample
    pub matrices_dirty: bool,

    /// Potentiometer 0: current resistance (ohms)
    pub pot_0_resistance: f64,
    /// Potentiometer 0: previous timestep resistance (trapezoidal A_neg)
    pub pot_0_resistance_prev: f64,

    // --- Runtime-adjustable device parameters ---
    /// Device 0 IS (Diode) — runtime adjustable
    pub device_0_is: f64,
    /// Device 0 N_VT (Diode) — runtime adjustable
    pub device_0_n_vt: f64,
    /// Device 1 IS (Bjt) — runtime adjustable
    pub device_1_is: f64,
    /// Device 1 VT (Bjt) — runtime adjustable
    pub device_1_vt: f64,
    /// Device 1 BETA_F (Bjt) — runtime adjustable
    pub device_1_bf: f64,
    /// Device 1 BETA_R (Bjt) — runtime adjustable
    pub device_1_br: f64,
    /// Device 2 IS (Bjt) — runtime adjustable
    pub device_2_is: f64,
    /// Device 2 VT (Bjt) — runtime adjustable
    pub device_2_vt: f64,
    /// Device 2 BETA_F (Bjt) — runtime adjustable
    pub device_2_bf: f64,
    /// Device 2 BETA_R (Bjt) — runtime adjustable
    pub device_2_br: f64,

    // --- Authentic circuit noise (Phase 1) ---
    /// Per-source xoshiro256++ state — independent streams, no cross-correlation.
    pub noise_rng: [Xoshiro256pp; NOISE_THERMAL_N],
    /// Cached second Gaussian from Marsaglia polar pair.
    pub noise_gaussian_cache: [Option<f64>; NOISE_THERMAL_N],
    /// Master noise switch — runtime. Default false (opt-in).
    pub noise_enabled: bool,
    /// Master scalar applied to every noise source.
    pub noise_gain: f64,
    /// Scalar applied only to Johnson-Nyquist thermal sources.
    pub thermal_gain: f64,
    /// Circuit temperature [K]. Runtime-settable.
    pub temperature_k: f64,
    /// Master seed recorded for reset() re-derivation.
    pub noise_master_seed: u64,
    /// Precomputed sqrt(2·K_B·T·fs_internal) — BE-primary single-draw
    /// calibration (un-doubled; see NOISE.md 'Backward-Euler-primary
    /// stamps').
    pub noise_thermal_scale: f64,
    /// Effective internal sample rate (host_rate × OVERSAMPLING_FACTOR).
    /// Tracked so `set_temperature_k` can recompute `noise_thermal_scale`.
    pub noise_fs: f64,
    /// Per-source `sqrt(1/R)` — live mirror of `NOISE_THERMAL_SQRT_INV_R_DEFAULT`.
    /// Static entries stay at their baked value. Dynamic entries (`.pot` /
    /// `.wiper` / `.runtime R` members) are refreshed inside the matching
    /// `set_pot_N` / `set_runtime_R_<field>` setter.
    pub noise_thermal_sqrt_inv_r: [f64; NOISE_THERMAL_N],
    /// Per-source previous-draw buffer for the two-draw Nyquist-anti-alias
    /// scheme. Each thermal stamp uses `w_new + w_prev` where w_new is the
    /// current draw (amplitude scale/2) and w_prev is the previous draw.
    /// Zeroed at default(), reset(), and set_seed(). See NOISE.md 'Nyquist anti-aliasing'.
    pub noise_thermal_w_prev: [f64; NOISE_THERMAL_N],
    /// Per-source last-stamped `i_n` cache. Populated by the trap rhs
    /// stamp; replayed by the BE-fallback stamp so BE samples carry the
    /// same noise content as the trap solve they replaced (no audible
    /// dropout during BE cooldowns; same RNG sequence regardless of how
    /// many samples trip BE).
    pub noise_thermal_last_i_n: [f64; NOISE_THERMAL_N],
    /// Scalar applied to shot-noise sources (Phase 2) and pentode
    /// partition noise (Phase 5). Shared because partition is shot
    /// at a different barrier; one mute call silences both.
    pub shot_gain: f64,
    /// Precomputed `sqrt(4·Q_E·fs_internal)`. Shared between shot and
    /// partition: shot uses `noise_shot_scale · sqrt(|I_prev|)`,
    /// partition uses `noise_shot_scale · sqrt(I_p·I_s/(I_p+I_s))`.
    /// Updated by `set_sample_rate`.
    pub noise_shot_scale: f64,
    /// Per-source xoshiro256++ state for shot noise — salted so streams
    /// cannot share a prefix with thermal streams under any master seed.
    pub noise_shot_rng: [Xoshiro256pp; NOISE_SHOT_N],
    /// Cached second Gaussian from Marsaglia polar pair (shot stream).
    pub noise_shot_gaussian_cache: [Option<f64>; NOISE_SHOT_N],
    /// Per-source previous half-draw for the two-draw Nyquist-anti-alias
    /// pair (trap path only; BE-primary is single-draw). Zeroed at
    /// default(), reset(), and set_seed(). See NOISE.md 'Nyquist anti-aliasing'.
    pub noise_shot_w_prev: [f64; NOISE_SHOT_N],
    /// Per-source last-stamped `i_n` cache (BE-fallback replay).
    pub noise_shot_last_i_n: [f64; NOISE_SHOT_N],
}

impl Default for CircuitState {
    fn default() -> Self {
        // Noise state (thermal only in Phase 1)
        let fs_internal = SAMPLE_RATE * OVERSAMPLING_FACTOR as f64;
        // BE-primary: single-draw stamp at the un-doubled amplitude
        // sqrt(2*K_B*T*fs) — BE's LF kernel gain (A - A_neg = G) is 2x
        // trap's (2G), so the trap pair-sum stamp would be +6 dB hot.
        // See NOISE.md 'Backward-Euler-primary stamps'.
        let noise_thermal_scale = (2.0 * K_B * T_ROOM_K * fs_internal).sqrt();
        let noise_rng = seed_noise_rngs::<NOISE_THERMAL_N>(NOISE_MASTER_SEED_DEFAULT);
        // Shared shot/partition amplitude: sqrt(4·Q_E·fs).
        // Per-sample variance: σ² = 4·Q_E·|I|·fs. Same 2× trap-MNA
        // compensation as thermal (PSD 2·q·|I| on [0, fs/2] gives
        // naive σ² = q·|I|·fs; doubling to preserve DK-trap DC gain
        // yields 2·q·|I|·fs; amplitude expressed as sqrt(X·Q_E·|I|·fs)
        // has X=4). Partition reuses this scale with a different
        // per-sample sqrt(...) factor (I_p·I_s/(I_p+I_s) rather than
        // |I|).
        // BE-primary: half amplitude (X=1) — BE's full LF kernel gain
        // makes the trap X=4 stamp +6 dB hot. Partition consumes this
        // scale at full amplitude single-draw (its trap x0.5 pair-sum
        // factor is dropped in the stamp).
        let noise_shot_scale = (Q_E * fs_internal).sqrt();
        // Shot-noise streams: salted distinct from thermal streams.
        let noise_shot_rng =
            seed_noise_rngs_salted::<NOISE_SHOT_N>(NOISE_MASTER_SEED_DEFAULT, NOISE_SHOT_SALT);
        let mut state = Self {
            v_prev: DC_OP,
            i_nl_prev: DC_NL_I,
            i_nl_prev_prev: DC_NL_I,
            dc_operating_point: DC_OP,
            input_prev: 0.0,
            last_nr_iterations: 0,
            diag_peak_output: 0.0,
            diag_clamp_count: 0,
            diag_nr_max_iter_count: 0,
            diag_region_exit_count: 0,
            diag_be_fallback_count: 0,
            diag_be_latch_count: 0,
            diag_active_set_pin_count: 0,
            diag_nan_reset_count: 0,
            diag_magnitude_reset_count: 0,
            diag_substep_count: 0,
            diag_refactor_count: 0,
            diag_ls_fail_count: 0,
            diag_voltage_damp_count: 0,
            chord_lu: [[0.0; N]; N],
            chord_dr: [1.0; N],
            chord_dc: [1.0; N],
            chord_perm: {
                {
                    let mut p = [0usize; N];
                    let mut i = 0;
                    while i < N {
                        p[i] = i;
                        i += 1;
                    }
                    p
                }
            },
            chord_j_dev: [0.0; M * M],
            chord_valid: false,
            chord_dense: false,
            a: A_DEFAULT,
            a_neg: A_NEG_DEFAULT,
            a_be: A_BE_DEFAULT,
            a_neg_be: A_NEG_BE_DEFAULT,
            s: S_DEFAULT,
            k: K_DEFAULT,
            s_ni: S_NI_DEFAULT,
            s_be: S_BE_DEFAULT,
            s_sub: S_SUB_DEFAULT,
            a_neg_sub: A_NEG_SUB_DEFAULT,
            k_sub: K_SUB_DEFAULT,
            s_ni_sub: S_NI_SUB_DEFAULT,
            k_be: K_BE_DEFAULT,
            s_ni_be: S_NI_BE_DEFAULT,
            g_work: G,
            c_work: C,
            current_sample_rate: 4.80000000000000000e4,
            matrices_dirty: false,
            pot_0_resistance: 9.99999999999999854e4,
            pot_0_resistance_prev: 9.99999999999999854e4,
            device_0_is: DEVICE_0_IS,
            device_0_n_vt: DEVICE_0_N_VT,
            device_1_is: DEVICE_1_IS,
            device_1_vt: DEVICE_1_VT,
            device_1_bf: DEVICE_1_BETA_F,
            device_1_br: DEVICE_1_BETA_R,
            device_2_is: DEVICE_2_IS,
            device_2_vt: DEVICE_2_VT,
            device_2_bf: DEVICE_2_BETA_F,
            device_2_br: DEVICE_2_BETA_R,
            noise_rng,
            noise_gaussian_cache: [None; NOISE_THERMAL_N],
            noise_enabled: false,
            noise_gain: 1.0,
            thermal_gain: 1.0,
            temperature_k: T_ROOM_K,
            noise_master_seed: NOISE_MASTER_SEED_DEFAULT,
            noise_thermal_scale,
            noise_fs: fs_internal,
            noise_thermal_sqrt_inv_r: NOISE_THERMAL_SQRT_INV_R_DEFAULT,
            noise_thermal_w_prev: [0.0; NOISE_THERMAL_N],
            noise_thermal_last_i_n: [0.0; NOISE_THERMAL_N],
            shot_gain: 1.0,
            noise_shot_scale,
            noise_shot_rng,
            noise_shot_gaussian_cache: [None; NOISE_SHOT_N],
            noise_shot_w_prev: [0.0; NOISE_SHOT_N],
            noise_shot_last_i_n: [0.0; NOISE_SHOT_N],
        };
        state.warmup();
        state
    }
}

impl CircuitState {
    /// Reset to DC operating point
    pub fn reset(&mut self) {
        self.v_prev = self.dc_operating_point;
        self.i_nl_prev = DC_NL_I;
        self.i_nl_prev_prev = DC_NL_I;
        self.input_prev = 0.0;
        self.last_nr_iterations = 0;
        self.chord_valid = false;
        self.diag_peak_output = 0.0;
        self.diag_clamp_count = 0;
        self.diag_nr_max_iter_count = 0;
        self.diag_region_exit_count = 0;
        self.diag_be_fallback_count = 0;
        self.diag_be_latch_count = 0;
        self.diag_active_set_pin_count = 0;
        self.diag_nan_reset_count = 0;
        self.diag_magnitude_reset_count = 0;
        self.diag_voltage_damp_count = 0;
        self.diag_substep_count = 0;
        self.diag_refactor_count = 0;
        self.diag_ls_fail_count = 0;
        self.g_work = G;
        self.c_work = C;
        self.pot_0_resistance = 9.99999999999999854e4;
        self.pot_0_resistance_prev = 9.99999999999999854e4;
        self.device_0_is = DEVICE_0_IS;
        self.device_0_n_vt = DEVICE_0_N_VT;
        self.device_1_is = DEVICE_1_IS;
        self.device_1_vt = DEVICE_1_VT;
        self.device_1_bf = DEVICE_1_BETA_F;
        self.device_1_br = DEVICE_1_BETA_R;
        self.device_2_is = DEVICE_2_IS;
        self.device_2_vt = DEVICE_2_VT;
        self.device_2_bf = DEVICE_2_BETA_F;
        self.device_2_br = DEVICE_2_BETA_R;
        // Re-seed noise RNGs (keeps noise_enabled, gains, temperature untouched).
        self.noise_rng = seed_noise_rngs::<NOISE_THERMAL_N>(self.noise_master_seed);
        self.noise_gaussian_cache = [None; NOISE_THERMAL_N];
        // Restore per-source sqrt(1/R) to defaults. Dynamic sources will
        // be re-updated by any subsequent set_pot_N / set_runtime_R call;
        // this mirrors how reset() restores pot_<i>_resistance to nominal.
        self.noise_thermal_sqrt_inv_r = NOISE_THERMAL_SQRT_INV_R_DEFAULT;
        // Clear two-draw buffer + BE-replay cache so silence after reset is true zero.
        self.noise_thermal_w_prev = [0.0; NOISE_THERMAL_N];
        self.noise_thermal_last_i_n = [0.0; NOISE_THERMAL_N];
        // Re-seed shot RNGs (same master, distinct salt from thermal).
        self.noise_shot_rng =
            seed_noise_rngs_salted::<NOISE_SHOT_N>(self.noise_master_seed, NOISE_SHOT_SALT);
        self.noise_shot_gaussian_cache = [None; NOISE_SHOT_N];
        self.noise_shot_w_prev = [0.0; NOISE_SHOT_N];
        self.noise_shot_last_i_n = [0.0; NOISE_SHOT_N];
        if (self.current_sample_rate - SAMPLE_RATE).abs() < 0.5 {
            self.a = A_DEFAULT;
            self.a_neg = A_NEG_DEFAULT;
            self.a_be = A_BE_DEFAULT;
            self.a_neg_be = A_NEG_BE_DEFAULT;
            self.s = S_DEFAULT;
            self.k = K_DEFAULT;
            self.s_ni = S_NI_DEFAULT;
            self.s_be = S_BE_DEFAULT;
            self.k_be = K_BE_DEFAULT;
            self.s_ni_be = S_NI_BE_DEFAULT;
            self.s_sub = S_SUB_DEFAULT;
            self.a_neg_sub = A_NEG_SUB_DEFAULT;
            self.k_sub = K_SUB_DEFAULT;
            self.s_ni_sub = S_NI_SUB_DEFAULT;
        } else {
            self.rebuild_matrices(self.current_sample_rate * 1.0);
        }
        self.matrices_dirty = false;
        self.warmup();
    }

    /// Run silent warmup samples to settle into the correct operating point.
    ///
    /// Call after construction or reset() to ensure the circuit settles into
    /// the physically correct basin of attraction. Without warmup, circuits
    /// with high-gain op-amps may lock into a parasitic equilibrium.
    ///
    /// The default `CircuitState::default()` calls this automatically.
    pub fn warmup(&mut self) {
        for _ in 0..50 {
            process_sample(0.0, self);
        }
    }

    /// Set DC operating point (call after DC analysis)
    pub fn set_dc_operating_point(&mut self, v_dc: [f64; N]) {
        self.dc_operating_point = v_dc;
        self.v_prev = v_dc;
    }

    /// Read the baked DC operating point for this circuit.
    ///
    /// Solution to the nonlinear DC system computed at codegen time (at nominal
    /// pot/switch values) and frozen into `DC_OP`. Prefer this over `v_prev` when
    /// you want the *designed* bias point — `v_prev` carries per-sample dynamics.
    #[inline]
    pub fn dc_op(&self) -> &[f64; N] {
        &self.dc_operating_point
    }

    /// Pretty-print the DC operating point with user-assigned node names.
    ///
    /// Writes one line per named node to `stderr`. Intended for plugin
    /// bring-up diagnostics, not the audio thread (formatting allocates).
    pub fn dc_op_dump(&self) {
        let dc = &self.dc_operating_point;
        eprintln!("  V(IN) = {:+.4} V", dc[0]);
        eprintln!("  V(MID_IN) = {:+.4} V", dc[1]);
        eprintln!("  V(BASE1) = {:+.4} V", dc[2]);
        eprintln!("  V(COLL1) = {:+.4} V", dc[3]);
        eprintln!("  V(EMIT1) = {:+.4} V", dc[4]);
        eprintln!("  V(VCC) = {:+.4} V", dc[5]);
        eprintln!("  V(FB) = {:+.4} V", dc[6]);
        eprintln!("  V(COLL2) = {:+.4} V", dc[7]);
        eprintln!("  V(EMIT2A) = {:+.4} V", dc[8]);
        eprintln!("  V(EMIT2B) = {:+.4} V", dc[9]);
        eprintln!("  V(NODE_C6) = {:+.4} V", dc[10]);
        eprintln!("  V(OUT) = {:+.4} V", dc[11]);
    }

    /// Recompute all sample-rate-dependent matrices for a new sample rate.
    ///
    /// Call this once during plugin initialization (NOT on the audio thread).
    /// Rebuilds A, A_neg, A_be, A_neg_be from stored G and C matrices.
    pub fn set_sample_rate(&mut self, sample_rate: f64) {
        if !(sample_rate > 0.0 && sample_rate.is_finite()) {
            return;
        }

        // Noise: recompute rate-dependent scales for the new rate.
        self.noise_fs = sample_rate * OVERSAMPLING_FACTOR as f64;
        self.noise_thermal_scale = (2.0 * K_B * self.temperature_k * self.noise_fs).sqrt();
        self.noise_shot_scale = (Q_E * self.noise_fs).sqrt();

        self.current_sample_rate = sample_rate;

        // If same as codegen sample rate, reset to defaults
        if (sample_rate - SAMPLE_RATE).abs() < 0.5 {
            let all_default = true
                && (self.pot_0_resistance - 9.99999999999999854e4).abs()
                    <= 9.99999999999999854e4 * 1e-6;
            if all_default {
                self.a = A_DEFAULT;
                self.a_neg = A_NEG_DEFAULT;
                self.a_be = A_BE_DEFAULT;
                self.a_neg_be = A_NEG_BE_DEFAULT;
                self.s = S_DEFAULT;
                self.s_be = S_BE_DEFAULT;
                self.k = K_DEFAULT;
                self.s_ni = S_NI_DEFAULT;
                self.k_be = K_BE_DEFAULT;
                self.s_ni_be = S_NI_BE_DEFAULT;
                self.s_sub = S_SUB_DEFAULT;
                self.a_neg_sub = A_NEG_SUB_DEFAULT;
                self.k_sub = K_SUB_DEFAULT;
                self.s_ni_sub = S_NI_SUB_DEFAULT;
                // POLICY: transient state — oversampler filter history,
                // DC-blocker history, solver v_prev/i_nl history — is
                // PRESERVED here. Only coefficients and matrices are
                // restored: a same-rate call is a no-op reconfiguration
                // and must not click (DK-template parity).
                return;
            }
            // Same rate but pots/switches are off-default: rebuild the
            // matrices at the live values. Rate-dependent coefficients
            // equal their baked defaults at this rate; transient state
            // is preserved (see POLICY above).
            self.rebuild_matrices(sample_rate * 1.0);
            return;
        }

        let internal_rate = sample_rate * 1.0;
        self.rebuild_matrices(internal_rate);
    }

    /// Recompute A, A_neg, A_be, A_neg_be from G and C.
    ///
    /// Called by set_sample_rate, set_pot, and set_switch.
    /// Also recomputes the Schur matrices S, K, S_NI (and BE variants),
    /// which includes O(N^3) matrix inversion.
    pub fn rebuild_matrices(&mut self, internal_rate: f64) {
        let alpha = internal_rate; // backward Euler: alpha = 1/T
        let alpha_be = internal_rate;
        let alpha_sub = 4.0 * internal_rate; // trap at 2× rate

        for i in 0..N {
            for j in 0..N {
                self.a[i][j] = self.g_work[i][j] + alpha * self.c_work[i][j];
                self.a_neg[i][j] = alpha * self.c_work[i][j];
                self.a_be[i][j] = self.g_work[i][j] + alpha_be * self.c_work[i][j];
                self.a_neg_be[i][j] = alpha_be * self.c_work[i][j];
            }
        }
        for i in 0..N {
            for j in 0..N {
                self.a_neg_sub[i][j] = alpha_sub * self.c_work[i][j] - self.g_work[i][j];
            }
        }
        for i in 12..13 {
            for j in 0..N {
                self.a_neg[i][j] = 0.0;
                self.a_neg_be[i][j] = 0.0;
            }
        }
        for i in 12..13 {
            for j in 0..N {
                self.a_neg_sub[i][j] = 0.0;
            }
        }

        // Recompute S = A^{-1} (trapezoidal)
        if let Some(inv) = invert_n(&self.a) {
            self.s = inv;
            // S_NI = S * N_i
            for i in 0..N {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += self.s[i][a] * N_I[a][j];
                    }
                    self.s_ni[i][j] = sum;
                }
            }
            // K = N_v * S_NI
            for i in 0..M {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += N_V[i][a] * self.s_ni[a][j];
                    }
                    self.k[i][j] = sum;
                }
            }
        }
        // Recompute S_be = A_be^{-1} (backward Euler)
        if let Some(inv) = invert_n(&self.a_be) {
            self.s_be = inv;
            // S_NI = S * N_i
            for i in 0..N {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += self.s_be[i][a] * N_I[a][j];
                    }
                    self.s_ni_be[i][j] = sum;
                }
            }
            // K = N_v * S_NI
            for i in 0..M {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += N_V[i][a] * self.s_ni_be[a][j];
                    }
                    self.k_be[i][j] = sum;
                }
            }
        }

        // Invalidate chord LU cache (matrices changed)
        self.chord_valid = false;
    }

    /// Current resistance of runtime resistor `r_ldr` (ohms).
    #[inline]
    pub fn r_ldr(&self) -> f64 {
        self.pot_0_resistance
    }

    /// Set runtime resistor `r_ldr` (clamped to [1000.0..1000000.0] ohms).
    ///
    /// Updates g_work and rebuilds all matrices (O(N^3)).
    /// Call per-block, not per-sample.
    pub fn set_runtime_R_r_ldr(&mut self, resistance: f64) {
        if !resistance.is_finite() {
            return;
        }
        let r = resistance.clamp(RUNTIME_R_R_LDR_MIN, RUNTIME_R_R_LDR_MAX);
        if (r - self.pot_0_resistance).abs() < 1e-12 {
            return;
        }

        // Delta conductance: stamp into A, A_neg, A_be (NOT A_neg_be: no G term)
        let delta_g = 1.0 / r - 1.0 / self.pot_0_resistance;
        self.a[6][6] += delta_g;
        self.a_neg[6][6] -= delta_g;
        self.a_be[6][6] += delta_g;

        // Update working G for sample rate rebuild consistency
        self.g_work[6][6] += delta_g;
        self.pot_0_resistance = r;
        self.matrices_dirty = true;
        self.noise_thermal_sqrt_inv_r[10] = (1.0 / r).sqrt();
    }

    // --- Noise controls (Phase 1) ---

    /// Turn circuit noise on or off. When off, all per-sample RNG calls are skipped.
    pub fn set_noise_enabled(&mut self, on: bool) {
        self.noise_enabled = on;
    }

    /// Master scalar applied to every noise source (post-per-category).
    pub fn set_noise_gain(&mut self, gain: f64) {
        self.noise_gain = gain;
    }

    /// Scalar applied only to Johnson-Nyquist thermal sources.
    pub fn set_thermal_gain(&mut self, gain: f64) {
        self.thermal_gain = gain;
    }

    /// Circuit temperature in Kelvin. 290 K is standard (~16.85 °C).
    /// Cold gear is quieter: 77 K (liquid N2) ≈ −5.76 dB, 3 K ≈ −19.9 dB.
    pub fn set_temperature_k(&mut self, kelvin: f64) {
        if !(kelvin.is_finite() && kelvin > 0.0) {
            return;
        }
        self.temperature_k = kelvin;
        // Recompute thermal_scale at the currently-set sample rate.
        self.noise_thermal_scale = (2.0 * K_B * kelvin * self.noise_fs).sqrt();
    }

    /// Scalar applied to shot (Phase 2 junction) noise and pentode
    /// partition (Phase 5) sources. Both are shot at different barriers
    /// — one knob mutes both. Runtime-settable. Set to `0.0` to mute
    /// shot/partition content without touching thermal.
    pub fn set_shot_gain(&mut self, gain: f64) {
        self.shot_gain = gain;
    }

    /// Set the master seed. `0` → entropy-seeded from system clock.
    /// Any nonzero value → deterministic (same seed → bit-identical noise).
    pub fn set_seed(&mut self, master: u64) {
        self.noise_master_seed = master;
        self.noise_rng = seed_noise_rngs::<NOISE_THERMAL_N>(master);
        self.noise_gaussian_cache = [None; NOISE_THERMAL_N];
        self.noise_thermal_w_prev = [0.0; NOISE_THERMAL_N];
        self.noise_thermal_last_i_n = [0.0; NOISE_THERMAL_N];
        self.noise_shot_rng = seed_noise_rngs_salted::<NOISE_SHOT_N>(master, NOISE_SHOT_SALT);
        self.noise_shot_gaussian_cache = [None; NOISE_SHOT_N];
        self.noise_shot_w_prev = [0.0; NOISE_SHOT_N];
        self.noise_shot_last_i_n = [0.0; NOISE_SHOT_N];
    }
}

// =============================================================================
// MATRIX INVERSION (for rebuild_matrices)
// =============================================================================

/// Invert an N×N matrix via LU factorization with partial pivoting.
/// Returns None if the matrix is singular (pivot < 1e-30).
///
/// Called three times per `rebuild_matrices` on the nodal path
/// (S = A^-1, S_be = A_be^-1, S_sub = A_sub^-1), so factor-then-
/// solve uses ~half the work of the prior Gauss-Jordan on an
/// augmented [A | I] matrix and halves the stack footprint.
#[inline(never)]
fn invert_n(a: &[[f64; N]; N]) -> Option<[[f64; N]; N]> {
    let mut lu = *a;
    let mut perm = [0usize; N];
    for i in 0..N {
        perm[i] = i;
    }

    for k in 0..N {
        let mut max_row = k;
        let mut max_val = lu[k][k].abs();
        for i in (k + 1)..N {
            let v = lu[i][k].abs();
            if v > max_val {
                max_val = v;
                max_row = i;
            }
        }
        if max_val < 1e-30 {
            return None;
        }
        if max_row != k {
            lu.swap(k, max_row);
            perm.swap(k, max_row);
        }
        let pivot = lu[k][k];
        for i in (k + 1)..N {
            let m = lu[i][k] / pivot;
            lu[i][k] = m;
            for j in (k + 1)..N {
                lu[i][j] -= m * lu[k][j];
            }
        }
    }

    let mut result = [[0.0f64; N]; N];
    for col in 0..N {
        let mut b = [0.0f64; N];
        let mut start = N;
        for i in 0..N {
            if perm[i] == col {
                b[i] = 1.0;
                start = i;
                break;
            }
        }
        for i in (start + 1)..N {
            let mut sum = b[i];
            for j in start..i {
                sum -= lu[i][j] * b[j];
            }
            b[i] = sum;
        }
        for i in (0..N).rev() {
            let mut sum = b[i];
            for j in (i + 1)..N {
                sum -= lu[i][j] * b[j];
            }
            let pivot = lu[i][i];
            if pivot.abs() < 1e-30 {
                return None;
            }
            b[i] = sum / pivot;
        }
        for i in 0..N {
            result[i][col] = b[i];
        }
    }

    Some(result)
}

// =============================================================================
// PROCESS SAMPLE (Schur complement: M-dim NR via precomputed S = A^{-1})
// =============================================================================

/// Process a single audio sample through the circuit.
///
/// Uses Schur complement NR: precomputes S = A^{-1}, iterates in M-space.
/// Cost: O(N^2) linear prediction + O(M^3) per NR iteration.
#[inline]
pub fn process_sample(input: f64, state: &mut CircuitState) -> [f64; NUM_OUTPUTS] {
    let input = if input.is_finite() {
        input.clamp(-100.0, 100.0)
    } else {
        0.0
    };

    // Lazy rebuild: batch all pot/switch changes into one matrix rebuild
    if state.matrices_dirty {
        state.rebuild_matrices(state.current_sample_rate * OVERSAMPLING_FACTOR as f64);
        state.matrices_dirty = false;
    }

    for v in state.v_prev.iter_mut() {
        *v = *v + 1e-25 - 1e-25;
    }
    for v in state.i_nl_prev.iter_mut() {
        *v = *v + 1e-25 - 1e-25;
    }

    // Step 1: Build RHS (sparse A_neg * v_prev + sparse N_i * i_nl_prev)
    let mut rhs = RHS_CONST;
    rhs[0] += state.a_neg[0][0] * state.v_prev[0];
    rhs[1] += state.a_neg[1][1] * state.v_prev[1];
    rhs[1] += state.a_neg[1][2] * state.v_prev[2];
    rhs[2] += state.a_neg[2][1] * state.v_prev[1];
    rhs[2] += state.a_neg[2][2] * state.v_prev[2];
    rhs[2] += state.a_neg[2][3] * state.v_prev[3];
    rhs[2] += state.a_neg[2][4] * state.v_prev[4];
    rhs[3] += state.a_neg[3][2] * state.v_prev[2];
    rhs[3] += state.a_neg[3][3] * state.v_prev[3];
    rhs[3] += state.a_neg[3][7] * state.v_prev[7];
    rhs[3] += state.a_neg[3][8] * state.v_prev[8];
    rhs[4] += state.a_neg[4][2] * state.v_prev[2];
    rhs[4] += state.a_neg[4][4] * state.v_prev[4];
    rhs[4] += state.a_neg[4][6] * state.v_prev[6];
    rhs[6] += state.a_neg[6][4] * state.v_prev[4];
    rhs[6] += state.a_neg[6][6] * state.v_prev[6];
    rhs[7] += state.a_neg[7][3] * state.v_prev[3];
    rhs[7] += state.a_neg[7][7] * state.v_prev[7];
    rhs[7] += state.a_neg[7][10] * state.v_prev[10];
    rhs[8] += state.a_neg[8][3] * state.v_prev[3];
    rhs[8] += state.a_neg[8][8] * state.v_prev[8];
    rhs[10] += state.a_neg[10][7] * state.v_prev[7];
    rhs[10] += state.a_neg[10][10] * state.v_prev[10];

    let input_conductance = 1.0 / INPUT_RESISTANCE;
    // Input source (backward Euler: V_in * G_in)
    rhs[INPUT_NODE] += input * input_conductance;

    // Authentic circuit noise — Phases 1 (thermal) + 2 (shot).
    // Skipped entirely (zero RNG calls) when noise_enabled is false.
    if state.noise_enabled {
        // BE-primary single-draw thermal stamp (un-doubled amplitude; no
        // w[n]+w[n-1] pair — BE damps z=-1 itself, and the pair-sum's
        // cos^2 envelope would add a spurious -3 dB @ fs/4 droop).
        let scale_th = state.noise_thermal_scale * state.noise_gain * state.thermal_gain;
        if scale_th != 0.0 {
            for k in 0..NOISE_THERMAL_N {
                let g = gaussian(&mut state.noise_rng[k], &mut state.noise_gaussian_cache[k]);
                let i_n = scale_th * state.noise_thermal_sqrt_inv_r[k] * g;
                state.noise_thermal_last_i_n[k] = i_n;
                let ni = NOISE_THERMAL_NODE_I[k];
                let nj = NOISE_THERMAL_NODE_J[k];
                if ni > 0 {
                    rhs[ni - 1] += i_n;
                }
                if nj > 0 {
                    rhs[nj - 1] -= i_n;
                }
            }
        } else {
            // scale==0 (gain or thermal_gain muted): clear cache so BE replay
            // doesn't re-inject the last enabled-mode i_n.
            state.noise_thermal_last_i_n = [0.0; NOISE_THERMAL_N];
        }
        // Shot: `|I_prev|` is the one-sample-lagged junction current from
        // `state.i_nl_prev` (inaudible lag; lets the stamp run before NR).
        // The gate includes `shot_gain` so hosts can mute shot alone.
        // BE-primary: single-draw sqrt(q·|I_prev|·fs) (BE damps z=-1 itself).
        let shot_scale = state.noise_shot_scale * state.noise_gain * state.shot_gain;
        if shot_scale != 0.0 {
            for k in 0..NOISE_SHOT_N {
                let i_abs = state.i_nl_prev[NOISE_SHOT_SLOT_IDX[k]].abs();
                if i_abs < 1e-15 {
                    continue;
                }
                let g = gaussian(
                    &mut state.noise_shot_rng[k],
                    &mut state.noise_shot_gaussian_cache[k],
                );
                let i_n = shot_scale * i_abs.sqrt() * g;
                state.noise_shot_last_i_n[k] = i_n;
                let ni = NOISE_SHOT_NODE_I[k];
                let nj = NOISE_SHOT_NODE_J[k];
                if ni > 0 {
                    rhs[ni - 1] += i_n;
                }
                if nj > 0 {
                    rhs[nj - 1] -= i_n;
                }
            }
        } else {
            state.noise_shot_last_i_n = [0.0; NOISE_SHOT_N];
        }
    } else {
        // noise_enabled=false: clear caches so a future BE replay during a
        // disabled-noise span doesn't re-inject the last enabled-mode i_n.
        state.noise_thermal_last_i_n = [0.0; NOISE_THERMAL_N];
        state.noise_shot_last_i_n = [0.0; NOISE_SHOT_N];
    }

    // Step 2: Linear prediction v_pred = S * rhs (O(N^2))
    let mut v_pred = [0.0f64; N];
    for i in 0..N {
        let mut sum = 0.0;
        for j in 0..N {
            sum += state.s[i][j] * rhs[j];
        }
        v_pred[i] = sum;
    }

    // Step 3: Extract device voltages p = N_v * v_pred (sparse)
    let mut p = [0.0f64; M];
    p[0] = N_V[0][2] * v_pred[2];
    p[1] = N_V[1][2] * v_pred[2] + N_V[1][4] * v_pred[4];
    p[2] = N_V[2][2] * v_pred[2] + N_V[2][3] * v_pred[3];
    p[3] = N_V[3][3] * v_pred[3] + N_V[3][8] * v_pred[8];
    p[4] = N_V[4][3] * v_pred[3] + N_V[4][7] * v_pred[7];

    // Step 4: M-dim Newton-Raphson (Schur complement)
    // First-order predictor warm start
    let mut i_nl = [0.0f64; M];
    for i in 0..M {
        i_nl[i] = 2.0 * state.i_nl_prev[i] - state.i_nl_prev_prev[i];
    }
    state.last_nr_iterations = MAX_ITER as u32;

    for iter in 0..MAX_ITER {
        // 4a. Compute controlling voltages: v_d = p + K * i_nl
        let v_d0 = p[0]
            + state.k[0][0] * i_nl[0]
            + state.k[0][1] * i_nl[1]
            + state.k[0][2] * i_nl[2]
            + state.k[0][3] * i_nl[3]
            + state.k[0][4] * i_nl[4];
        let v_d1 = p[1]
            + state.k[1][0] * i_nl[0]
            + state.k[1][1] * i_nl[1]
            + state.k[1][2] * i_nl[2]
            + state.k[1][3] * i_nl[3]
            + state.k[1][4] * i_nl[4];
        let v_d2 = p[2]
            + state.k[2][0] * i_nl[0]
            + state.k[2][1] * i_nl[1]
            + state.k[2][2] * i_nl[2]
            + state.k[2][3] * i_nl[3]
            + state.k[2][4] * i_nl[4];
        let v_d3 = p[3]
            + state.k[3][0] * i_nl[0]
            + state.k[3][1] * i_nl[1]
            + state.k[3][2] * i_nl[2]
            + state.k[3][3] * i_nl[3]
            + state.k[3][4] * i_nl[4];
        let v_d4 = p[4]
            + state.k[4][0] * i_nl[0]
            + state.k[4][1] * i_nl[1]
            + state.k[4][2] * i_nl[2]
            + state.k[4][3] * i_nl[3]
            + state.k[4][4] * i_nl[4];

        // 4b. Evaluate device currents and Jacobians
        let i_dev0 = diode_current(v_d0, state.device_0_is, state.device_0_n_vt);
        let jdev_0_0 = diode_conductance(v_d0, state.device_0_is, state.device_0_n_vt);
        let (i_dev1, i_dev2, bjt1_jac) = bjt_with_parasitics(
            v_d1,
            v_d2,
            state.device_1_is,
            state.device_1_vt,
            DEVICE_1_NF,
            DEVICE_1_NR,
            state.device_1_bf,
            state.device_1_br,
            DEVICE_1_SIGN,
            DEVICE_1_USE_GP,
            DEVICE_1_VAF,
            DEVICE_1_VAR,
            DEVICE_1_IKF,
            DEVICE_1_IKR,
            DEVICE_1_ISE,
            DEVICE_1_NE,
            DEVICE_1_ISC,
            DEVICE_1_NC,
            DEVICE_1_RB,
            DEVICE_1_RC,
            DEVICE_1_RE,
        );
        let jdev_1_1 = bjt1_jac[0];
        let jdev_1_2 = bjt1_jac[1];
        let jdev_2_1 = bjt1_jac[2];
        let jdev_2_2 = bjt1_jac[3];
        let (i_dev3, i_dev4, bjt2_jac) = bjt_with_parasitics(
            v_d3,
            v_d4,
            state.device_2_is,
            state.device_2_vt,
            DEVICE_2_NF,
            DEVICE_2_NR,
            state.device_2_bf,
            state.device_2_br,
            DEVICE_2_SIGN,
            DEVICE_2_USE_GP,
            DEVICE_2_VAF,
            DEVICE_2_VAR,
            DEVICE_2_IKF,
            DEVICE_2_IKR,
            DEVICE_2_ISE,
            DEVICE_2_NE,
            DEVICE_2_ISC,
            DEVICE_2_NC,
            DEVICE_2_RB,
            DEVICE_2_RC,
            DEVICE_2_RE,
        );
        let jdev_3_3 = bjt2_jac[0];
        let jdev_3_4 = bjt2_jac[1];
        let jdev_4_3 = bjt2_jac[2];
        let jdev_4_4 = bjt2_jac[3];

        // 4c. Residuals: f(i) = i_nl - i_dev = 0
        let f0 = i_nl[0] - i_dev0;
        let f1 = i_nl[1] - i_dev1;
        let f2 = i_nl[2] - i_dev2;
        let f3 = i_nl[3] - i_dev3;
        let f4 = i_nl[4] - i_dev4;

        // 4d. Jacobian: J[i][j] = delta_ij - jdev * K
        let j0_0 = 1.0 - jdev_0_0 * state.k[0][0];
        let j0_1 = 0.0 - jdev_0_0 * state.k[0][1];
        let j0_2 = 0.0 - jdev_0_0 * state.k[0][2];
        let j0_3 = 0.0 - jdev_0_0 * state.k[0][3];
        let j0_4 = 0.0 - jdev_0_0 * state.k[0][4];
        let j1_0 = 0.0 - jdev_1_1 * state.k[1][0] - jdev_1_2 * state.k[2][0];
        let j1_1 = 1.0 - jdev_1_1 * state.k[1][1] - jdev_1_2 * state.k[2][1];
        let j1_2 = 0.0 - jdev_1_1 * state.k[1][2] - jdev_1_2 * state.k[2][2];
        let j1_3 = 0.0 - jdev_1_1 * state.k[1][3] - jdev_1_2 * state.k[2][3];
        let j1_4 = 0.0 - jdev_1_1 * state.k[1][4] - jdev_1_2 * state.k[2][4];
        let j2_0 = 0.0 - jdev_2_1 * state.k[1][0] - jdev_2_2 * state.k[2][0];
        let j2_1 = 0.0 - jdev_2_1 * state.k[1][1] - jdev_2_2 * state.k[2][1];
        let j2_2 = 1.0 - jdev_2_1 * state.k[1][2] - jdev_2_2 * state.k[2][2];
        let j2_3 = 0.0 - jdev_2_1 * state.k[1][3] - jdev_2_2 * state.k[2][3];
        let j2_4 = 0.0 - jdev_2_1 * state.k[1][4] - jdev_2_2 * state.k[2][4];
        let j3_0 = 0.0 - jdev_3_3 * state.k[3][0] - jdev_3_4 * state.k[4][0];
        let j3_1 = 0.0 - jdev_3_3 * state.k[3][1] - jdev_3_4 * state.k[4][1];
        let j3_2 = 0.0 - jdev_3_3 * state.k[3][2] - jdev_3_4 * state.k[4][2];
        let j3_3 = 1.0 - jdev_3_3 * state.k[3][3] - jdev_3_4 * state.k[4][3];
        let j3_4 = 0.0 - jdev_3_3 * state.k[3][4] - jdev_3_4 * state.k[4][4];
        let j4_0 = 0.0 - jdev_4_3 * state.k[3][0] - jdev_4_4 * state.k[4][0];
        let j4_1 = 0.0 - jdev_4_3 * state.k[3][1] - jdev_4_4 * state.k[4][1];
        let j4_2 = 0.0 - jdev_4_3 * state.k[3][2] - jdev_4_4 * state.k[4][2];
        let j4_3 = 0.0 - jdev_4_3 * state.k[3][3] - jdev_4_4 * state.k[4][3];
        let j4_4 = 1.0 - jdev_4_3 * state.k[3][4] - jdev_4_4 * state.k[4][4];

        // Solve 5x5 system via inline Gaussian elimination
        let mut a = [
            [j0_0, j0_1, j0_2, j0_3, j0_4],
            [j1_0, j1_1, j1_2, j1_3, j1_4],
            [j2_0, j2_1, j2_2, j2_3, j2_4],
            [j3_0, j3_1, j3_2, j3_3, j3_4],
            [j4_0, j4_1, j4_2, j4_3, j4_4],
        ];
        let mut b = [f0, f1, f2, f3, f4];
        let mut singular = false;
        for col in 0..5 {
            let mut max_row = col;
            let mut max_val = a[col][col].abs();
            for row in (col + 1)..5 {
                if a[row][col].abs() > max_val {
                    max_val = a[row][col].abs();
                    max_row = row;
                }
            }
            if max_val < 1e-15 {
                singular = true;
                break;
            }
            if max_row != col {
                a.swap(col, max_row);
                b.swap(col, max_row);
            }
            let pivot = a[col][col];
            for row in (col + 1)..5 {
                let factor = a[row][col] / pivot;
                for j in (col + 1)..5 {
                    a[row][j] -= factor * a[col][j];
                }
                b[row] -= factor * b[col];
            }
        }
        if !singular {
            for i in (0..5).rev() {
                let mut sum = b[i];
                for j in (i + 1)..5 {
                    sum -= a[i][j] * b[j];
                }
                if a[i][i].abs() < 1e-15 {
                    singular = true;
                    break;
                }
                b[i] = sum / a[i][i];
            }
        }
        if !singular {
            let delta0 = b[0];
            let delta1 = b[1];
            let delta2 = b[2];
            let delta3 = b[3];
            let delta4 = b[4];
            // Trial voltages: apply full NR step, then limit
            let i_trial0 = i_nl[0] - delta0;
            let i_trial1 = i_nl[1] - delta1;
            let i_trial2 = i_nl[2] - delta2;
            let i_trial3 = i_nl[3] - delta3;
            let i_trial4 = i_nl[4] - delta4;
            let v_trial0 = p[0]
                + state.k[0][0] * i_trial0
                + state.k[0][1] * i_trial1
                + state.k[0][2] * i_trial2
                + state.k[0][3] * i_trial3
                + state.k[0][4] * i_trial4;
            let v_trial1 = p[1]
                + state.k[1][0] * i_trial0
                + state.k[1][1] * i_trial1
                + state.k[1][2] * i_trial2
                + state.k[1][3] * i_trial3
                + state.k[1][4] * i_trial4;
            let v_trial2 = p[2]
                + state.k[2][0] * i_trial0
                + state.k[2][1] * i_trial1
                + state.k[2][2] * i_trial2
                + state.k[2][3] * i_trial3
                + state.k[2][4] * i_trial4;
            let v_trial3 = p[3]
                + state.k[3][0] * i_trial0
                + state.k[3][1] * i_trial1
                + state.k[3][2] * i_trial2
                + state.k[3][3] * i_trial3
                + state.k[3][4] * i_trial4;
            let v_trial4 = p[4]
                + state.k[4][0] * i_trial0
                + state.k[4][1] * i_trial1
                + state.k[4][2] * i_trial2
                + state.k[4][3] * i_trial3
                + state.k[4][4] * i_trial4;
            let mut any_limited = false;
            let dv_trial0 = v_trial0 - v_d0;
            let v_lim0 = if dv_trial0.abs() > 1e-4 {
                pnjlim(v_trial0, v_d0, state.device_0_n_vt, DEVICE_0_VCRIT)
            } else {
                v_trial0
            };
            let dv_trial1 = v_trial1 - v_d1;
            let v_lim1 = if dv_trial1.abs() > 1e-4 {
                pnjlim(v_trial1, v_d1, state.device_1_vt, DEVICE_1_VCRIT)
            } else {
                v_trial1
            };
            let dv_trial2 = v_trial2 - v_d2;
            let v_lim2 = if dv_trial2.abs() > 1e-4 {
                pnjlim(v_trial2, v_d2, state.device_1_vt, DEVICE_1_VCRIT)
            } else {
                v_trial2
            };
            let dv_trial3 = v_trial3 - v_d3;
            let v_lim3 = if dv_trial3.abs() > 1e-4 {
                pnjlim(v_trial3, v_d3, state.device_2_vt, DEVICE_2_VCRIT)
            } else {
                v_trial3
            };
            let dv_trial4 = v_trial4 - v_d4;
            let v_lim4 = if dv_trial4.abs() > 1e-4 {
                pnjlim(v_trial4, v_d4, state.device_2_vt, DEVICE_2_VCRIT)
            } else {
                v_trial4
            };
            let mut global_alpha = 1.0_f64;
            {
                let dv_lim = v_lim0 - v_d0;
                if dv_trial0.abs() > 1e-15 {
                    let r = if dv_trial0 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial0).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim1 - v_d1;
                if dv_trial1.abs() > 1e-15 {
                    let r = if dv_trial1 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial1).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim2 - v_d2;
                if dv_trial2.abs() > 1e-15 {
                    let r = if dv_trial2 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial2).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim3 - v_d3;
                if dv_trial3.abs() > 1e-15 {
                    let r = if dv_trial3 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial3).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim4 - v_d4;
                if dv_trial4.abs() > 1e-15 {
                    let r = if dv_trial4 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial4).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let max_dv = (dv_trial0 * global_alpha)
                    .abs()
                    .max((dv_trial1 * global_alpha).abs())
                    .max((dv_trial2 * global_alpha).abs())
                    .max((dv_trial3 * global_alpha).abs())
                    .max((dv_trial4 * global_alpha).abs());
                if max_dv > 3.500000 {
                    global_alpha *= 3.500000 / max_dv;
                    any_limited = true;
                }
            }
            i_nl[0] -= global_alpha * delta0;
            i_nl[1] -= global_alpha * delta1;
            i_nl[2] -= global_alpha * delta2;
            i_nl[3] -= global_alpha * delta3;
            i_nl[4] -= global_alpha * delta4;

            // Convergence check (SPICE RELTOL=0.001, VNTOL=1e-6)
            if !any_limited {
                let mut nr_converged = true;
                {
                    let dv = dv_trial0 * global_alpha;
                    let threshold = 1e-3 * v_d0.abs().max((v_d0 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial1 * global_alpha;
                    let threshold = 1e-3 * v_d1.abs().max((v_d1 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial2 * global_alpha;
                    let threshold = 1e-3 * v_d2.abs().max((v_d2 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial3 * global_alpha;
                    let threshold = 1e-3 * v_d3.abs().max((v_d3 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial4 * global_alpha;
                    let threshold = 1e-3 * v_d4.abs().max((v_d4 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                if nr_converged {
                    state.last_nr_iterations = iter as u32;
                    break;
                }
            }
        } else {
            // Singular Jacobian — damped fallback (0.5 * residual, adaptive clamp)
            {
                let clamp = (i_nl[0].abs() * 0.1).max(0.01);
                i_nl[0] -= (f0 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[1].abs() * 0.1).max(0.01);
                i_nl[1] -= (f1 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[2].abs() * 0.1).max(0.01);
                i_nl[2] -= (f2 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[3].abs() * 0.1).max(0.01);
                i_nl[3] -= (f3 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[4].abs() * 0.1).max(0.01);
                i_nl[4] -= (f4 * 0.5).clamp(-clamp, clamp);
            }
        }
    }

    // Step 5: Recover full node voltages: v = v_pred + S_NI * i_nl
    let mut v = v_pred;
    for i in 0..N {
        for j in 0..M {
            v[i] += state.s_ni[i][j] * i_nl[j];
        }
    }
    let converged = state.last_nr_iterations < MAX_ITER as u32;

    // Backward Euler fallback
    if !converged {
        if state.last_nr_iterations >= MAX_ITER as u32 {
            state.diag_nr_max_iter_count += 1;
        }
        state.diag_be_fallback_count += 1;

        // Rebuild RHS with backward Euler matrices
        let mut rhs_be = [0.0f64; N];
        for i in 0..N {
            let mut sum = RHS_CONST_BE[i];
            for j in 0..N {
                sum += state.a_neg_be[i][j] * state.v_prev[j];
            }
            rhs_be[i] = sum;
        }
        rhs_be[INPUT_NODE] += input * input_conductance;

        // BE-fallback noise replay (re-stamps cached trap-stamp i_n into rhs_be).
        if state.noise_enabled {
            for k in 0..NOISE_THERMAL_N {
                let i_n = state.noise_thermal_last_i_n[k];
                let ni = NOISE_THERMAL_NODE_I[k];
                let nj = NOISE_THERMAL_NODE_J[k];
                if ni > 0 {
                    rhs_be[ni - 1] += i_n;
                }
                if nj > 0 {
                    rhs_be[nj - 1] -= i_n;
                }
            }
            for k in 0..NOISE_SHOT_N {
                let i_n = state.noise_shot_last_i_n[k];
                let ni = NOISE_SHOT_NODE_I[k];
                let nj = NOISE_SHOT_NODE_J[k];
                if ni > 0 {
                    rhs_be[ni - 1] += i_n;
                }
                if nj > 0 {
                    rhs_be[nj - 1] -= i_n;
                }
            }
        }

        // BE linear prediction: v_pred_be = S_be * rhs_be
        let mut v_pred_be = [0.0f64; N];
        for i in 0..N {
            let mut sum = 0.0;
            for j in 0..N {
                sum += state.s_be[i][j] * rhs_be[j];
            }
            v_pred_be[i] = sum;
        }

        let mut p_be = [0.0f64; M];
        for i in 0..M {
            let mut sum = 0.0;
            for j in 0..N {
                sum += N_V[i][j] * v_pred_be[j];
            }
            p_be[i] = sum;
        }

        // Reset i_nl to predictor for BE attempt
        for i in 0..M {
            i_nl[i] = 2.0 * state.i_nl_prev[i] - state.i_nl_prev_prev[i];
        }

        for _iter in 0..MAX_ITER {
            let v_d0 = p_be[0]
                + state.k_be[0][0] * i_nl[0]
                + state.k_be[0][1] * i_nl[1]
                + state.k_be[0][2] * i_nl[2]
                + state.k_be[0][3] * i_nl[3]
                + state.k_be[0][4] * i_nl[4];
            let v_d1 = p_be[1]
                + state.k_be[1][0] * i_nl[0]
                + state.k_be[1][1] * i_nl[1]
                + state.k_be[1][2] * i_nl[2]
                + state.k_be[1][3] * i_nl[3]
                + state.k_be[1][4] * i_nl[4];
            let v_d2 = p_be[2]
                + state.k_be[2][0] * i_nl[0]
                + state.k_be[2][1] * i_nl[1]
                + state.k_be[2][2] * i_nl[2]
                + state.k_be[2][3] * i_nl[3]
                + state.k_be[2][4] * i_nl[4];
            let v_d3 = p_be[3]
                + state.k_be[3][0] * i_nl[0]
                + state.k_be[3][1] * i_nl[1]
                + state.k_be[3][2] * i_nl[2]
                + state.k_be[3][3] * i_nl[3]
                + state.k_be[3][4] * i_nl[4];
            let v_d4 = p_be[4]
                + state.k_be[4][0] * i_nl[0]
                + state.k_be[4][1] * i_nl[1]
                + state.k_be[4][2] * i_nl[2]
                + state.k_be[4][3] * i_nl[3]
                + state.k_be[4][4] * i_nl[4];

            let i_dev0 = diode_current(v_d0, state.device_0_is, state.device_0_n_vt);
            let jdev_0_0 = diode_conductance(v_d0, state.device_0_is, state.device_0_n_vt);
            let (i_dev1, i_dev2, bjt1_jac) = bjt_with_parasitics(
                v_d1,
                v_d2,
                state.device_1_is,
                state.device_1_vt,
                DEVICE_1_NF,
                DEVICE_1_NR,
                state.device_1_bf,
                state.device_1_br,
                DEVICE_1_SIGN,
                DEVICE_1_USE_GP,
                DEVICE_1_VAF,
                DEVICE_1_VAR,
                DEVICE_1_IKF,
                DEVICE_1_IKR,
                DEVICE_1_ISE,
                DEVICE_1_NE,
                DEVICE_1_ISC,
                DEVICE_1_NC,
                DEVICE_1_RB,
                DEVICE_1_RC,
                DEVICE_1_RE,
            );
            let jdev_1_1 = bjt1_jac[0];
            let jdev_1_2 = bjt1_jac[1];
            let jdev_2_1 = bjt1_jac[2];
            let jdev_2_2 = bjt1_jac[3];
            let (i_dev3, i_dev4, bjt2_jac) = bjt_with_parasitics(
                v_d3,
                v_d4,
                state.device_2_is,
                state.device_2_vt,
                DEVICE_2_NF,
                DEVICE_2_NR,
                state.device_2_bf,
                state.device_2_br,
                DEVICE_2_SIGN,
                DEVICE_2_USE_GP,
                DEVICE_2_VAF,
                DEVICE_2_VAR,
                DEVICE_2_IKF,
                DEVICE_2_IKR,
                DEVICE_2_ISE,
                DEVICE_2_NE,
                DEVICE_2_ISC,
                DEVICE_2_NC,
                DEVICE_2_RB,
                DEVICE_2_RC,
                DEVICE_2_RE,
            );
            let jdev_3_3 = bjt2_jac[0];
            let jdev_3_4 = bjt2_jac[1];
            let jdev_4_3 = bjt2_jac[2];
            let jdev_4_4 = bjt2_jac[3];

            let f0 = i_nl[0] - i_dev0;
            let f1 = i_nl[1] - i_dev1;
            let f2 = i_nl[2] - i_dev2;
            let f3 = i_nl[3] - i_dev3;
            let f4 = i_nl[4] - i_dev4;

            let j0_0 = 1.0 - jdev_0_0 * state.k_be[0][0];
            let j0_1 = 0.0 - jdev_0_0 * state.k_be[0][1];
            let j0_2 = 0.0 - jdev_0_0 * state.k_be[0][2];
            let j0_3 = 0.0 - jdev_0_0 * state.k_be[0][3];
            let j0_4 = 0.0 - jdev_0_0 * state.k_be[0][4];
            let j1_0 = 0.0 - jdev_1_1 * state.k_be[1][0] - jdev_1_2 * state.k_be[2][0];
            let j1_1 = 1.0 - jdev_1_1 * state.k_be[1][1] - jdev_1_2 * state.k_be[2][1];
            let j1_2 = 0.0 - jdev_1_1 * state.k_be[1][2] - jdev_1_2 * state.k_be[2][2];
            let j1_3 = 0.0 - jdev_1_1 * state.k_be[1][3] - jdev_1_2 * state.k_be[2][3];
            let j1_4 = 0.0 - jdev_1_1 * state.k_be[1][4] - jdev_1_2 * state.k_be[2][4];
            let j2_0 = 0.0 - jdev_2_1 * state.k_be[1][0] - jdev_2_2 * state.k_be[2][0];
            let j2_1 = 0.0 - jdev_2_1 * state.k_be[1][1] - jdev_2_2 * state.k_be[2][1];
            let j2_2 = 1.0 - jdev_2_1 * state.k_be[1][2] - jdev_2_2 * state.k_be[2][2];
            let j2_3 = 0.0 - jdev_2_1 * state.k_be[1][3] - jdev_2_2 * state.k_be[2][3];
            let j2_4 = 0.0 - jdev_2_1 * state.k_be[1][4] - jdev_2_2 * state.k_be[2][4];
            let j3_0 = 0.0 - jdev_3_3 * state.k_be[3][0] - jdev_3_4 * state.k_be[4][0];
            let j3_1 = 0.0 - jdev_3_3 * state.k_be[3][1] - jdev_3_4 * state.k_be[4][1];
            let j3_2 = 0.0 - jdev_3_3 * state.k_be[3][2] - jdev_3_4 * state.k_be[4][2];
            let j3_3 = 1.0 - jdev_3_3 * state.k_be[3][3] - jdev_3_4 * state.k_be[4][3];
            let j3_4 = 0.0 - jdev_3_3 * state.k_be[3][4] - jdev_3_4 * state.k_be[4][4];
            let j4_0 = 0.0 - jdev_4_3 * state.k_be[3][0] - jdev_4_4 * state.k_be[4][0];
            let j4_1 = 0.0 - jdev_4_3 * state.k_be[3][1] - jdev_4_4 * state.k_be[4][1];
            let j4_2 = 0.0 - jdev_4_3 * state.k_be[3][2] - jdev_4_4 * state.k_be[4][2];
            let j4_3 = 0.0 - jdev_4_3 * state.k_be[3][3] - jdev_4_4 * state.k_be[4][3];
            let j4_4 = 1.0 - jdev_4_3 * state.k_be[3][4] - jdev_4_4 * state.k_be[4][4];

            let mut a = [
                [j0_0, j0_1, j0_2, j0_3, j0_4],
                [j1_0, j1_1, j1_2, j1_3, j1_4],
                [j2_0, j2_1, j2_2, j2_3, j2_4],
                [j3_0, j3_1, j3_2, j3_3, j3_4],
                [j4_0, j4_1, j4_2, j4_3, j4_4],
            ];
            let mut b = [f0, f1, f2, f3, f4];
            let mut singular = false;
            for col in 0..5 {
                let mut max_row = col;
                let mut max_val = a[col][col].abs();
                for row in (col + 1)..5 {
                    if a[row][col].abs() > max_val {
                        max_val = a[row][col].abs();
                        max_row = row;
                    }
                }
                if max_val < 1e-15 {
                    singular = true;
                    break;
                }
                if max_row != col {
                    a.swap(col, max_row);
                    b.swap(col, max_row);
                }
                let pivot = a[col][col];
                for row in (col + 1)..5 {
                    let factor = a[row][col] / pivot;
                    for j in (col + 1)..5 {
                        a[row][j] -= factor * a[col][j];
                    }
                    b[row] -= factor * b[col];
                }
            }
            if !singular {
                for i in (0..5).rev() {
                    let mut sum = b[i];
                    for j in (i + 1)..5 {
                        sum -= a[i][j] * b[j];
                    }
                    if a[i][i].abs() < 1e-15 {
                        singular = true;
                        break;
                    }
                    b[i] = sum / a[i][i];
                }
            }
            if !singular {
                let delta0 = b[0];
                let delta1 = b[1];
                let delta2 = b[2];
                let delta3 = b[3];
                let delta4 = b[4];
                let dv0 = -(state.k_be[0][0] * delta0
                    + state.k_be[0][1] * delta1
                    + state.k_be[0][2] * delta2
                    + state.k_be[0][3] * delta3
                    + state.k_be[0][4] * delta4);
                let dv1 = -(state.k_be[1][0] * delta0
                    + state.k_be[1][1] * delta1
                    + state.k_be[1][2] * delta2
                    + state.k_be[1][3] * delta3
                    + state.k_be[1][4] * delta4);
                let dv2 = -(state.k_be[2][0] * delta0
                    + state.k_be[2][1] * delta1
                    + state.k_be[2][2] * delta2
                    + state.k_be[2][3] * delta3
                    + state.k_be[2][4] * delta4);
                let dv3 = -(state.k_be[3][0] * delta0
                    + state.k_be[3][1] * delta1
                    + state.k_be[3][2] * delta2
                    + state.k_be[3][3] * delta3
                    + state.k_be[3][4] * delta4);
                let dv4 = -(state.k_be[4][0] * delta0
                    + state.k_be[4][1] * delta1
                    + state.k_be[4][2] * delta2
                    + state.k_be[4][3] * delta3
                    + state.k_be[4][4] * delta4);
                let mut alpha = [1.0_f64; 5];
                let mut any_limited = false;
                if dv0.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d0 + dv0, v_d0, state.device_0_n_vt, DEVICE_0_VCRIT);
                    let ratio = ((v_lim - v_d0) / dv0).max(0.01);
                    if ratio < alpha[0] {
                        alpha[0] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv1.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d1 + dv1, v_d1, state.device_1_vt, DEVICE_1_VCRIT);
                    let ratio = ((v_lim - v_d1) / dv1).max(0.01);
                    if ratio < alpha[1] {
                        alpha[1] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv2.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d2 + dv2, v_d2, state.device_1_vt, DEVICE_1_VCRIT);
                    let ratio = ((v_lim - v_d2) / dv2).max(0.01);
                    if ratio < alpha[2] {
                        alpha[2] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv3.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d3 + dv3, v_d3, state.device_2_vt, DEVICE_2_VCRIT);
                    let ratio = ((v_lim - v_d3) / dv3).max(0.01);
                    if ratio < alpha[3] {
                        alpha[3] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv4.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d4 + dv4, v_d4, state.device_2_vt, DEVICE_2_VCRIT);
                    let ratio = ((v_lim - v_d4) / dv4).max(0.01);
                    if ratio < alpha[4] {
                        alpha[4] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                let mut alpha_scalar =
                    alpha[0].min(alpha[1].min(alpha[2].min(alpha[3].min(alpha[4]))));
                // Global voltage backstop: limit max voltage change to 3.5V
                let max_dv = (dv0 * alpha_scalar)
                    .abs()
                    .max((dv1 * alpha_scalar).abs())
                    .max((dv2 * alpha_scalar).abs())
                    .max((dv3 * alpha_scalar).abs())
                    .max((dv4 * alpha_scalar).abs());
                if max_dv > 3.500000 {
                    alpha_scalar *= (3.500000 / max_dv).max(0.1);
                }
                i_nl[0] -= alpha_scalar * delta0;
                i_nl[1] -= alpha_scalar * delta1;
                i_nl[2] -= alpha_scalar * delta2;
                i_nl[3] -= alpha_scalar * delta3;
                i_nl[4] -= alpha_scalar * delta4;
                // Convergence check (SPICE RELTOL=0.001, VNTOL=1e-6)
                if !any_limited {
                    let mut nr_converged = true;
                    {
                        let step = dv0 * alpha_scalar;
                        let v_new = v_d0 + step;
                        let threshold = 1e-3 * v_d0.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv1 * alpha_scalar;
                        let v_new = v_d1 + step;
                        let threshold = 1e-3 * v_d1.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv2 * alpha_scalar;
                        let v_new = v_d2 + step;
                        let threshold = 1e-3 * v_d2.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv3 * alpha_scalar;
                        let v_new = v_d3 + step;
                        let threshold = 1e-3 * v_d3.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv4 * alpha_scalar;
                        let v_new = v_d4 + step;
                        let threshold = 1e-3 * v_d4.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    if nr_converged {
                        state.last_nr_iterations = _iter as u32;
                        break;
                    }
                }
            } else {
                i_nl[0] -= (f0 * 0.5).clamp(-0.01, 0.01);
                i_nl[1] -= (f1 * 0.5).clamp(-0.01, 0.01);
                i_nl[2] -= (f2 * 0.5).clamp(-0.01, 0.01);
                i_nl[3] -= (f3 * 0.5).clamp(-0.01, 0.01);
                i_nl[4] -= (f4 * 0.5).clamp(-0.01, 0.01);
            }
        }

        // Recover full v from BE solve
        v = v_pred_be;
        for i in 0..N {
            for j in 0..M {
                v[i] += state.s_ni_be[i][j] * i_nl[j];
            }
        }
    }

    // NaN/Inf AND finite-but-implausible-magnitude check BEFORE state
    // update — prevents corruption of v_prev/i_nl_prev. A saturated solve
    // (exp() clamp, near-singular LU) can produce a huge-but-finite value
    // that bypasses is_finite() and would otherwise propagate forever.
    // Mirrors the DK-path reset in templates/rust/process_sample.rs.tera (Step 7).
    let v_is_finite = v.iter().all(|x| x.is_finite());
    if !v_is_finite || v.iter().any(|x| x.abs() > STATE_MAX_PLAUSIBLE_MAGNITUDE) {
        state.v_prev = state.dc_operating_point;
        state.i_nl_prev = DC_NL_I;
        state.i_nl_prev_prev = DC_NL_I;
        state.input_prev = 0.0;
        // Noise: clear two-draw lag + BE-replay caches (RNG seed preserved).
        state.noise_thermal_w_prev = [0.0; NOISE_THERMAL_N];
        state.noise_thermal_last_i_n = [0.0; NOISE_THERMAL_N];
        state.noise_shot_w_prev = [0.0; NOISE_SHOT_N];
        state.noise_shot_last_i_n = [0.0; NOISE_SHOT_N];
        if v_is_finite {
            state.diag_magnitude_reset_count += 1;
        } else {
            state.diag_nan_reset_count += 1;
        }
        let mut nan_out = [0.0f64; NUM_OUTPUTS];
        nan_out[0] = 0.00000000000000000e0;
        return nan_out;
    }

    // State update
    state.v_prev = v;
    state.input_prev = input;
    state.i_nl_prev_prev = state.i_nl_prev;
    state.i_nl_prev = i_nl;
    state.pot_0_resistance_prev = state.pot_0_resistance;

    // Region-exit characterization: samples where a pentode's grid
    // conducts (Vgk > 0) or a BJT saturates (Vbc forward) — the regions
    // the grid-off / forward-active reductions assume are never entered.
    if (v[2] - v[3]) > 0.0 {
        state.diag_region_exit_count += 1;
    }
    if (v[3] - v[7]) > 0.0 {
        state.diag_region_exit_count += 1;
    }
    // Extract outputs, DC blocking, and scaling
    let mut output = [0.0f64; NUM_OUTPUTS];
    for out_idx in 0..NUM_OUTPUTS {
        let raw_out = v[OUTPUT_NODES[out_idx]];
        let raw_out = if raw_out.is_finite() { raw_out } else { 0.0 };
        let scaled = raw_out * OUTPUT_SCALES[out_idx];
        let abs_out = scaled.abs();
        if abs_out > state.diag_peak_output {
            state.diag_peak_output = abs_out;
        }
        output[out_idx] = if scaled.is_finite() { scaled } else { 0.0 };
    }
    output
}
